  ('codex_metrics_sum', 'hot_cold'),
  ('otel_logs', 'hot_cold'),
  ('otel_metrics_gauge', 'hot_cold'),
  ('otel_metrics_sum', 'hot_cold'),
  ('otel_metrics_sum_hourly', 'hot_cold'),
